function pgCharset(o){
  o=o||{};
  var c='';
  if(o.upper!==false) c+='ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  if(o.lower!==false) c+='abcdefghijklmnopqrstuvwxyz';
  if(o.digit!==false) c+='0123456789';
  if(o.symbol) c+='!@#$%^&*()-_=+[]{};:,.<>?';
  return c;
}
function pgRng(){
  if(typeof window!=='undefined' && window.crypto && window.crypto.getRandomValues){
    var a=new Uint32Array(1); return function(){ window.crypto.getRandomValues(a); return a[0]/4294967296; };
  }
  return Math.random;
}
function pgPick(cs, rnd){ return cs.charAt(Math.floor(rnd()*cs.length)); }
function pgGenerate(len, o, rnd){
  if(!rnd) rnd=pgRng();
  var cs=pgCharset(o);
  if(!cs) return { error:'字符集为空' };
  if(len<1||len>256) return { error:'长度需在 1–256' };
  var s='';
  for(var i=0;i<len;i++) s+=pgPick(cs, rnd);
  return { error:null, pw:s, charset:cs };
}
function pgEntropy(pw, o){ var cs=pgCharset(o); return pw.length*Math.log2(cs.length||1); }
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { pgCharset:pgCharset, pgGenerate:pgGenerate, pgEntropy:pgEntropy, pgRng:pgRng };
}
if (typeof window !== 'undefined') {
  window.PassgenForgePure = { pgCharset:pgCharset, pgGenerate:pgGenerate, pgEntropy:pgEntropy, pgRng:pgRng };
}
